import{_ as e,o as a,c as i,a0 as n}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Run a CI runner fleet","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/ci-runner-fleet.md","filePath":"how-to/ci-runner-fleet.md"}'),t={name:"how-to/ci-runner-fleet.md"};function o(l,s,h,r,p,d){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="run-a-ci-runner-fleet" tabindex="-1">Run a CI runner fleet <a class="header-anchor" href="#run-a-ci-runner-fleet" aria-label="Permalink to &quot;Run a CI runner fleet&quot;">​</a></h1><p>A <em>fleet</em> is N ephemeral peregrin nodes booted on throwaway hosts (CI runners, cloud VMs, containers), joined to a hub that outlives them. The org no longer uses GitHub Actions — the reusable-workflow examples this page once carried are gone — but the topology is host-agnostic: any orchestrator that can start a process and set env vars can boot a node.</p><h2 id="topology-—-read-this-first" tabindex="-1">Topology — read this first <a class="header-anchor" href="#topology-—-read-this-first" aria-label="Permalink to &quot;Topology — read this first&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        hub (your machine / server / long-lived host)</span></span>
<span class="line"><span>         │  PEREGRIN_NODES=&quot;ci-1=http://…:18787@tok;ci-2=…&quot;</span></span>
<span class="line"><span>         │  ▲ hub→node ops only work if the hub can REACH the node</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>   ┌─────┴──────────────────────────┐</span></span>
<span class="line"><span>   │  runner ci-1   runner ci-2 …   │   hosted CI: NO inbound</span></span>
<span class="line"><span>   │  peregrin serve --ephemeral    │   connections — hub cannot dial</span></span>
<span class="line"><span>   └─────┬──────────────────────────┘   them; useful directions are</span></span>
<span class="line"><span>         │ outbound: snapshots → hub,  │   OUTBOUND only:</span></span>
<span class="line"><span>         │ \`peregrin\` CLI → hub/node   │</span></span></code></pre></div><ul><li><strong>Hub stays home.</strong> It owns the entity plane view, the lock book, and the outbox. Ephemeral runners join it as ordinary nodes — auth is config (<code>PEREGRIN_NODES=id=url[@token];…</code> on the hub, <code>PEREGRIN_TOKEN</code> on each node), never pairing.</li><li><strong>Runners are ephemeral nodes.</strong> On SIGTERM each flushes snapshots of <code>live</code>/<code>locked</code> entities — locally under <code>PEREGRIN_SNAPSHOT_DIR</code> (persist it as a job artifact or on a volume) and/or handed off to <code>PEREGRIN_SNAPSHOT_TARGET</code> so the entity resumes where it can keep running.</li><li><strong>Ops route via ownership.</strong> The hub arbitrates locks (<code>hypha-control</code>, ~30s stale threshold) and forwards ops to the node that owns an entity — <em>if it can reach it</em>. On hosted CI runners that means outbound-only: snapshots and client verbs. For real hub→runner op routing use self-hosted runners on a tailnet/LAN the hub can dial, or have the runner dial out.</li></ul><h2 id="booting-a-node" tabindex="-1">Booting a node <a class="header-anchor" href="#booting-a-node" aria-label="Permalink to &quot;Booting a node&quot;">​</a></h2><p>The per-node mechanics — env vars, snapshot destinations, lock behavior — are in <a href="./run-a-ci-node.html">Run a CI runner node</a>. The short version for any orchestrator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18787</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shared-secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # REQUIRED off-loopback</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_EPHEMERAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RUNNER_TEMP/peregrin</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># optional handoff:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SNAPSHOT_TARGET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://hub:18787</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SNAPSHOT_NODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">home-node    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># when the target is a hub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ephemeral</span></span></code></pre></div><p>Seed <code>$PEREGRIN_HOME/node.json</code> with a stable id <strong>before first boot</strong> so the hub&#39;s <code>PEREGRIN_NODES</code> can name it (<code>ci-1=…</code>) instead of chasing auto-minted <code>node_&lt;hex&gt;</code> ids.</p><h2 id="installing-peregrin-on-the-runner" tabindex="-1">Installing peregrin on the runner <a class="header-anchor" href="#installing-peregrin-on-the-runner" aria-label="Permalink to &quot;Installing peregrin on the runner&quot;">​</a></h2><p>Until published releases exist, install from source — the <code>peregrin</code> command is a tamias <code>bins[]</code> shim, so stage the pack payload and let tamias deploy it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url.&quot;https://github.com/&quot;.insteadOf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ssh://git@github.com/&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/peregrin.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peregrin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # release bins → libraries/peregrin/{drivers,tools}/bin/&lt;triple&gt;/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/peregrin</span></span></code></pre></div><p>Two things to know:</p><ul><li><strong>The ssh→https rewrite is required.</strong> peregrin&#39;s manifest pins <code>sepia</code>/<code>tamias</code>/<code>hypha</code> crates as <code>ssh://git@github.com/…</code> deps; runners have no SSH keys. The repos are public, so https works.</li><li><strong>It compiles the dependency graph</strong> — expect several minutes on a cold cache (<code>cargo xtask pack</code> release-builds the driver plus the <code>peregrin-node</code>/<code>peregrin-hub</code> payload bins). Once release tarballs ship (<code>peregrin-&lt;target&gt;.tar.gz</code> — payload bins only; the <code>peregrin</code> command still comes from the tamias pack), unpack them onto <code>PATH</code> instead of building.</li></ul><h2 id="session-plane-honesty" tabindex="-1">Session plane honesty <a class="header-anchor" href="#session-plane-honesty" aria-label="Permalink to &quot;Session plane honesty&quot;">​</a></h2><p><code>PEREGRIN_SESSION_PLANE=local</code> (or <code>inprocess</code>) links <code>sepia-session</code><strong>in-process</strong> — the node boots with only the <code>peregrin</code> binary, no <code>sepia</code> install. Campaign and substrate work (<code>kind=&quot;campaign&quot;</code>, entities, ops, snapshots) needs nothing more. Real agent sessions still need the sepia <strong>drivers</strong> (<code>sepia-driver-*</code> on <code>PATH</code>) and, if you unset the plane override, the <code>sepia</code> binary itself (<code>PEREGRIN_SEPIA</code> or PATH).</p><h2 id="fleet-labels-and-dispatch" tabindex="-1">Fleet labels and dispatch <a class="header-anchor" href="#fleet-labels-and-dispatch" aria-label="Permalink to &quot;Fleet labels and dispatch&quot;">​</a></h2><p>Give runners capabilities the hub can schedule on: set <code>PEREGRIN_RUNNER_LABELS=ci,linux</code> (comma-separated) on each node — they surface in <code>/api/node</code> <code>capabilities</code>. Campaigns declare <code>runs_on: [label, …]</code> (AND match) and the hub&#39;s fleet dispatcher routes <code>campaign.start</code> ops to eligible nodes, preferring durable over ephemeral. See <a href="./../reference/fleet-runners.html">Fleet runners</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./run-a-ci-node.html">Run a CI runner node</a> — the single-node mechanics (env vars, snapshot destinations, locks).</li><li><a href="./run-a-hub.html">Run a hub</a> — <code>PEREGRIN_NODES</code> config on the hub side.</li></ul>`,20)])])}const g=e(t,[["render",o]]);export{k as __pageData,g as default};
